struct InferenceOutput {
    int class_id;
    const char* class_name;
    float confidence;
    float probabilities[NUM_CLASSES];
};

inline InferenceOutput forwardPass(const float features[NUM_FEATURES]) {
    // 1. Standardize features
    float x_scaled[NUM_FEATURES];
    for (int i = 0; i < NUM_FEATURES; ++i) {
        float s = (SCALER_SCALE[i] > 1e-7f) ? SCALER_SCALE[i] : 1.0f;
        x_scaled[i] = (features[i] - SCALER_MEAN[i]) / s;
    }

    // 2. Layer 1 (Dense 64 + ReLU)
    float h1[HIDDEN_1_UNITS];
    for (int j = 0; j < HIDDEN_1_UNITS; ++j) {
        float sum = BIAS_LAYER_0[j];
        for (int i = 0; i < NUM_FEATURES; ++i) {
            sum += x_scaled[i] * WEIGHTS_LAYER_0[i][j];
        }
        h1[j] = (sum > 0.0f) ? sum : 0.0f; // ReLU
    }

    // 3. Layer 2 (Dense 32 + ReLU)
    float h2[HIDDEN_2_UNITS];
    for (int j = 0; j < HIDDEN_2_UNITS; ++j) {
        float sum = BIAS_LAYER_1[j];
        for (int i = 0; i < HIDDEN_1_UNITS; ++i) {
            sum += h1[i] * WEIGHTS_LAYER_1[i][j];
        }
        h2[j] = (sum > 0.0f) ? sum : 0.0f; // ReLU
    }

    // 4. Layer 3 (Dense 8 + Softmax)
    float logits[NUM_CLASSES];
    float max_logit = -1e9f;
    for (int j = 0; j < NUM_CLASSES; ++j) {
        float sum = BIAS_LAYER_2[j];
        for (int i = 0; i < HIDDEN_2_UNITS; ++i) {
            sum += h2[i] * WEIGHTS_LAYER_2[i][j];
        }
        logits[j] = sum;
        if (sum > max_logit) {
            max_logit = sum;
        }
    }

    float sum_exp = 0.0f;
    InferenceOutput out;
    for (int j = 0; j < NUM_CLASSES; ++j) {
        out.probabilities[j] = std::exp(logits[j] - max_logit);
        sum_exp += out.probabilities[j];
    }

    int best_id = 0;
    float best_prob = 0.0f;
    for (int j = 0; j < NUM_CLASSES; ++j) {
        out.probabilities[j] /= sum_exp;
        if (out.probabilities[j] > best_prob) {
            best_prob = out.probabilities[j];
            best_id = j;
        }
    }

    out.class_id = best_id;
    out.class_name = CLASS_NAMES[best_id];
    out.confidence = best_prob;
    return out;
}

